#!/usr/bin/env python3
import sys,os,tempfile,json,zlib,base64
from pathlib import Path
sys.dont_write_bytecode=True
os.umask(0o077)
PAYLOAD=''
if __name__=='__main__':
 with tempfile.TemporaryDirectory(prefix='gsun-v6-activate-') as tmp:
  root=Path(tmp)
  for name,text in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))).items():
   if Path(name).name!=name:raise SystemExit('STOP_BUNDLE_PATH')
   (root/name).write_text(text)
  sys.path.insert(0,tmp)
  import activate_v6
  sys.exit(activate_v6.main())
